using BARANG.Core.Domain.Catalog;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace BARANG.Core.Infrastructure.Persistence.Configurations;

internal static class SupplierLifecycleConfigurationBase
{
    public static void Base<T>(EntityTypeBuilder<T> b, string table) where T : class { b.ToTable(table); b.HasKey("Id"); b.Property<Guid>("Id").HasColumnName("id").ValueGeneratedNever(); b.Property<Guid>("CompanyId").HasColumnName("company_id"); b.HasOne<Domain.Organization.Company>().WithMany().HasForeignKey("CompanyId").OnDelete(DeleteBehavior.Restrict); b.HasAlternateKey("CompanyId", "Id"); }
}
internal sealed class SupplierEvaluationConfiguration : IEntityTypeConfiguration<SupplierEvaluation> { public void Configure(EntityTypeBuilder<SupplierEvaluation> b) { SupplierLifecycleConfigurationBase.Base(b, "supplier_evaluations"); b.Property(x=>x.SupplierId).HasColumnName("supplier_id"); b.Property(x=>x.EvaluationDate).HasColumnName("evaluation_date"); b.Property(x=>x.PeriodStart).HasColumnName("period_start"); b.Property(x=>x.PeriodEnd).HasColumnName("period_end"); b.Property(x=>x.EvaluatorUserId).HasColumnName("evaluator_user_id"); b.Property(x=>x.OverallScore).HasColumnName("overall_score").HasPrecision(5,2); b.Property(x=>x.ResultStatus).HasColumnName("result_status").HasMaxLength(20); b.Property(x=>x.Notes).HasColumnName("notes").HasMaxLength(2000); b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc"); b.Property(x=>x.Version).HasColumnName("version").IsConcurrencyToken(); b.HasOne<Supplier>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.SupplierId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict); b.HasIndex(x=>new{x.CompanyId,x.SupplierId,x.EvaluationDate}); } }
internal sealed class SupplierEvaluationCriterionConfiguration : IEntityTypeConfiguration<SupplierEvaluationCriterion> { public void Configure(EntityTypeBuilder<SupplierEvaluationCriterion> b) { SupplierLifecycleConfigurationBase.Base(b,"supplier_evaluation_criteria"); b.Property(x=>x.EvaluationId).HasColumnName("evaluation_id"); b.Property(x=>x.CriterionId).HasColumnName("criterion_id"); b.Property(x=>x.Score).HasColumnName("score").HasPrecision(5,2); b.Property(x=>x.Comment).HasColumnName("comment").HasMaxLength(1000); b.HasOne<SupplierEvaluation>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.EvaluationId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Cascade); b.HasIndex(x=>new{x.CompanyId,x.EvaluationId,x.CriterionId}).IsUnique(); } }
internal sealed class SupplierQualityIncidentConfiguration : IEntityTypeConfiguration<SupplierQualityIncident> { public void Configure(EntityTypeBuilder<SupplierQualityIncident> b) { SupplierLifecycleConfigurationBase.Base(b,"supplier_quality_incidents"); b.Property(x=>x.SupplierId).HasColumnName("supplier_id"); b.Property(x=>x.IncidentType).HasColumnName("incident_type").HasMaxLength(40); b.Property(x=>x.IncidentDate).HasColumnName("incident_date"); b.Property(x=>x.Quantity).HasColumnName("quantity").HasPrecision(18,4); b.Property(x=>x.Status).HasColumnName("status").HasMaxLength(20); b.Property(x=>x.Description).HasColumnName("description").HasMaxLength(2000); b.Property(x=>x.CorrectiveAction).HasColumnName("corrective_action").HasMaxLength(2000); b.Property(x=>x.ResolvedDate).HasColumnName("resolved_date"); b.Property(x=>x.RecordedByUserId).HasColumnName("recorded_by_user_id"); b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc"); b.Property(x=>x.Version).HasColumnName("version").IsConcurrencyToken(); b.HasOne<Supplier>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.SupplierId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict); b.HasIndex(x=>new{x.CompanyId,x.SupplierId,x.IncidentDate}); } }
internal sealed class SupplierLifecycleProfileConfiguration : IEntityTypeConfiguration<SupplierLifecycleProfile> { public void Configure(EntityTypeBuilder<SupplierLifecycleProfile> b) { SupplierLifecycleConfigurationBase.Base(b,"supplier_lifecycle_profiles"); b.Property(x=>x.SupplierId).HasColumnName("supplier_id"); b.Property(x=>x.ApprovalStatus).HasColumnName("approval_status").HasMaxLength(20); b.Property(x=>x.QualityScore).HasColumnName("quality_score").HasPrecision(5,2); b.Property(x=>x.QcLevelId).HasColumnName("qc_level_id"); b.Property(x=>x.HoldReason).HasColumnName("hold_reason").HasMaxLength(500); b.Property(x=>x.HeldAtUtc).HasColumnName("held_at_utc"); b.Property(x=>x.HeldByUserId).HasColumnName("held_by_user_id"); b.Property(x=>x.HoldNotes).HasColumnName("hold_notes").HasMaxLength(2000); b.Property(x=>x.Version).HasColumnName("version").IsConcurrencyToken(); b.HasOne<Supplier>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.SupplierId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Cascade); b.HasIndex(x=>new{x.CompanyId,x.SupplierId}).IsUnique(); } }
internal sealed class SupplierContractConfiguration : IEntityTypeConfiguration<SupplierContract> { public void Configure(EntityTypeBuilder<SupplierContract> b) { SupplierLifecycleConfigurationBase.Base(b,"supplier_contracts"); b.Property(x=>x.SupplierId).HasColumnName("supplier_id"); b.Property(x=>x.ContractNumber).HasColumnName("contract_number").HasMaxLength(80); b.Property(x=>x.ContractTypeId).HasColumnName("contract_type_id"); b.Property(x=>x.StartDate).HasColumnName("start_date"); b.Property(x=>x.EndDate).HasColumnName("end_date"); b.Property(x=>x.Status).HasColumnName("status").HasMaxLength(20); b.Property(x=>x.Description).HasColumnName("description").HasMaxLength(2000); b.Property(x=>x.ContractValue).HasColumnName("contract_value").HasPrecision(18,2); b.Property(x=>x.CurrencyCode).HasColumnName("currency_code").HasMaxLength(3); b.Property(x=>x.FileId).HasColumnName("file_id"); b.Property(x=>x.FileVersionId).HasColumnName("file_version_id"); b.Property(x=>x.Version).HasColumnName("version").IsConcurrencyToken(); b.HasOne<Supplier>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.SupplierId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict); b.HasIndex(x=>new{x.CompanyId,x.ContractNumber}).IsUnique(); } }
internal sealed class SupplierDocumentConfiguration : IEntityTypeConfiguration<SupplierDocument> { public void Configure(EntityTypeBuilder<SupplierDocument> b) { SupplierLifecycleConfigurationBase.Base(b,"supplier_documents"); b.Property(x=>x.SupplierId).HasColumnName("supplier_id"); b.Property(x=>x.ContractId).HasColumnName("contract_id"); b.Property(x=>x.DocumentTypeId).HasColumnName("document_type_id"); b.Property(x=>x.DocumentNumber).HasColumnName("document_number").HasMaxLength(100); b.Property(x=>x.IssueDate).HasColumnName("issue_date"); b.Property(x=>x.ExpiryDate).HasColumnName("expiry_date"); b.Property(x=>x.Status).HasColumnName("status").HasMaxLength(20); b.Property(x=>x.Description).HasColumnName("description").HasMaxLength(2000); b.Property(x=>x.IssuingAuthority).HasColumnName("issuing_authority").HasMaxLength(300); b.Property(x=>x.FileId).HasColumnName("file_id"); b.Property(x=>x.FileVersionId).HasColumnName("file_version_id"); b.Property(x=>x.Version).HasColumnName("version").IsConcurrencyToken(); b.HasOne<Supplier>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.SupplierId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict); b.HasOne<SupplierContract>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.ContractId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict); b.HasIndex(x=>new{x.CompanyId,x.SupplierId,x.ExpiryDate}); } }
